from taf.sbts.oam.coam.admin.utils import raise_value_error


class WCDMAUplink(object):
    def __init__(self, dist_name, uarfcn, uplink_scrambling_code, in_sync_limit, out_sync_limit, auto_report):

        self.dist_name = dist_name

        self.uarfcn = self.validate_param('uarfcn',
                                          uarfcn,
                                          (0 <= uarfcn <= 4294967295))

        self.uplink_scrambling_code = self.validate_param('uplinkScramblingCode',
                                                          uplink_scrambling_code,
                                                          (0 <= uplink_scrambling_code <= 16777215))

        self.in_sync_limit = self.validate_param('inSyncLimit',
                                                 in_sync_limit,
                                                 (in_sync_limit is None or (0 <= in_sync_limit <= 4294967295)))

        self.out_sync_limit = self.validate_param('outSyncLimit',
                                                  out_sync_limit,
                                                  (out_sync_limit is None or (0 <= out_sync_limit <= 4294967295)))

        self.auto_report = self.validate_param('autoReport',
                                               auto_report,
                                               (auto_report is None or auto_report in (True, False)))

    @classmethod
    def from_response_dict(cls, response_dict):
        params = response_dict['params']
        dist_name = response_dict['wncel_rDN']

        uarfcn = params['uarfcn']
        uplink_scrambling_code = params['uplinkScramblingCode']
        in_sync_limit = params['inSyncLimit'] if 'inSyncLimit' in params else None
        out_sync_limit = params['outSyncLimit'] if 'outSyncLimit' in params else None
        auto_report = params['autoReport'] if 'autoReport' in params else None

        return cls(
            dist_name=dist_name,
            uarfcn=uarfcn,
            uplink_scrambling_code=uplink_scrambling_code,
            in_sync_limit=in_sync_limit,
            out_sync_limit=out_sync_limit,
            auto_report=auto_report,
        )

    def as_dict(self):
        attributes = {'wncel_rDN': self.dist_name,
                      'params': {'uarfcn': self.uarfcn,
                                 'uplinkScramblingCode': self.uplink_scrambling_code,
                                 'inSyncLimit': self.in_sync_limit,
                                 'outSyncLimit': self.out_sync_limit,
                                 'autoReport': self.auto_report,
                                 }
                      }

        attributes['params'] = {k: v for k, v in attributes['params'].items() if v is not None}

        return attributes

    @staticmethod
    def validate_param(param, value, valid):
        return value if valid else raise_value_error(
            param=param,
            value=str(value),
            subpage="tutorial-startWcdmaUplinkTest.html")
